import SwiftUI

// MARK: - 数据模型
struct Article: Identifiable, Decodable, Hashable {
    let id: Int
    let title: String
}

// MARK: - 网络服务（actor 保证内部可变状态的并发安全）
actor ArticleService {
    /// 模拟网络请求：延时 0.8 秒后返回数据
    func fetchArticles(keyword: String) async throws -> [Article] {
        // Task.sleep 对取消敏感，被取消时抛出 CancellationError
        try await Task.sleep(nanoseconds: 800_000_000)

        // 模拟业务校验失败
        guard !keyword.trimmingCharacters(in: .whitespaces).isEmpty else {
            throw URLError(.badURL)
        }

        // 模拟返回 5 条数据
        return (1...5).map { Article(id: $0, title: "\($0). 关于 \(keyword) 的文章") }
    }
}

// MARK: - 视图模型：@MainActor 保证状态更新发生在主线程
@MainActor
final class ArticleViewModel: ObservableObject {
    enum State: Equatable {
        case idle
        case loading
        case loaded([Article])
        case failed(String)
    }

    @Published private(set) var state: State = .idle

    private let service = ArticleService()
    private var requestID = 0   // 用于丢弃过期的响应

    func load(keyword: String) async {
        requestID += 1
        let currentID = requestID
        state = .loading

        do {
            let articles = try await service.fetchArticles(keyword: keyword)

            // 只接受最新一次请求的结果，防止旧数据覆盖新数据
            guard currentID == requestID else { return }
            state = .loaded(articles)
        } catch is CancellationError {
            // 视图消失 / 关键词变化导致的取消：静默处理，不打扰用户
            return
        } catch {
            guard currentID == requestID else { return }
            state = .failed(error.localizedDescription)
        }
    }
}

// MARK: - 视图
struct ArticleListView: View {
    @StateObject private var viewModel = ArticleViewModel()
    @State private var keyword = "SwiftUI"

    var body: some View {
        NavigationStack {
            Group {
                switch viewModel.state {
                case .idle:
                    ContentUnavailableView("输入关键词开始搜索",
                                           systemImage: "magnifyingglass")
                case .loading:
                    ProgressView("加载中…")
                case .loaded(let articles):
                    List(articles) { article in
                        Text(article.title)
                    }
                case .failed(let message):
                    ContentUnavailableView("加载失败",
                                           systemImage: "wifi.exclamationmark",
                                           description: Text(message))
                }
            }
            .navigationTitle("文章")
            .searchable(text: $keyword)
            // 关键词变化时：自动取消旧任务 → 启动新任务
            // 视图消失时：自动取消正在运行的任务
            .task(id: keyword) {
                await viewModel.load(keyword: keyword)
            }
        }
    }
}

